sp_widget.client_script:
api.controller = function($scope, $window) {
  var c = this;

  c.gridView       = true;
  c.activeCategory = 'all';
  c.filtered       = angular.copy(c.data.programs) || [];

  c.filterBy = function(cat) {
    c.activeCategory = cat;

    if (cat === 'all') {
      c.filtered = c.data.programs;
      return;
    }

    c.filtered = c.data.programs.filter(function(p) {
      return (p.program_category || '').trim() === cat.trim();
    });
  };

  c.viewDetails = function(program) {
    $window.location.href = '?id=grant_program_detail&sys_id=' + program.sys_id;
  };
};

sp_widget.css:
/* ─── Reset ───────────────────────────────────────────── */
.gp-programs-wrapper *,
.gp-programs-wrapper *::before,
.gp-programs-wrapper *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ─── Wrapper ─────────────────────────────────────────── */
.gp-programs-wrapper {
  font-family: 'Inter', 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  width: calc(100% + 30px);
  margin-left: -15px;
  margin-right: -15px;
}

/* ════════════════════════════════════════════════════════
   HERO HEADER — purple gradient
════════════════════════════════════════════════════════ */
.gp-programs-hero {
  background: linear-gradient(114deg, rgb(84, 60, 168) 17%, rgb(88, 107, 199) 114%);
  padding: 64px 0 56px;
}

.gp-programs-hero-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 60px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0;
}

/* Badge */
.gp-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.28);
  color: rgba(255,255,255,0.92);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 20px;
  backdrop-filter: blur(6px);
}

.gp-badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #7dd3fc;
  box-shadow: 0 0 6px rgba(125,211,252,0.8);
  flex-shrink: 0;
  animation: gpPulse 2.2s ease-in-out infinite;
}

@keyframes gpPulse {
  0%,100% { transform: scale(1); opacity: 1; }
  50%      { transform: scale(1.6); opacity: 0.5; }
}

/* Title */
.gp-programs-title {
  font-size: clamp(22px, 2.4vw, 32px);
  font-weight: 700;
  color: #ffffff;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 14px;
}

/* Subtitle */
.gp-programs-subtitle {
  font-size: 14px;
  color: rgba(255,255,255,0.72);
  line-height: 1.7;
  margin-bottom: 40px;
}

/* Stats row */
.gp-stats {
  display: flex;
  align-items: center;
  gap: 0;
  background: rgba(255,255,255,0.10);
  border: 1px solid rgba(255,255,255,0.16);
  border-radius: 14px;
  padding: 20px 32px;
  backdrop-filter: blur(6px);
}

.gp-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 0 32px;
}

.gp-stat:first-child { padding-left: 0; }
.gp-stat:last-child  { padding-right: 0; }

.gp-stat-num {
  font-size: 26px;
  font-weight: 700;
  color: #ffffff;
  line-height: 1;
}

.gp-stat-label {
  font-size: 11px;
  font-weight: 500;
  color: rgba(255,255,255,0.60);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

.gp-stat-divider {
  width: 1px;
  height: 36px;
  background: rgba(255,255,255,0.20);
  flex-shrink: 0;
}

/* ════════════════════════════════════════════════════════
   BODY — white background
════════════════════════════════════════════════════════ */
.gp-programs-body {
  background: #f9f9fb;
  padding: 40px 0 64px;
}

.gp-programs-body-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 60px;
}

/* ─── Filter bar ──────────────────────────────────────── */
.gp-filter-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}

.gp-filter-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.gp-filter-tab {
  font-size: 13px;
  font-weight: 500;
  color: #6b7280;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 100px;
  padding: 7px 16px;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
  font-family: inherit;
}

.gp-filter-tab:hover {
  border-color: #5443ad;
  color: #5443ad;
}

.gp-filter-tab--active {
  background: #5443ad;
  border-color: #5443ad;
  color: #ffffff !important;
}

/* View toggle */
.gp-view-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 4px;
  flex-shrink: 0;
}

.gp-toggle-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: #9ca3af;
  cursor: pointer;
  transition: all 0.18s ease;
}

.gp-toggle-btn--active {
  background: #5443ad;
  color: #ffffff;
}

/* ─── Grid ────────────────────────────────────────────── */
.gp-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.gp-grid--list {
  grid-template-columns: 1fr;
}

/* ─── Card ────────────────────────────────────────────── */
.gp-card {
  background: #ffffff;
  border: 1px solid #e9eaf0;
  border-radius: 14px;
  padding: 24px 24px 20px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transition: box-shadow 0.2s ease, transform 0.2s ease, border-color 0.2s ease;
}

.gp-card:hover {
  box-shadow: 0 8px 32px rgba(84,67,173,0.12);
  transform: translateY(-3px);
  border-color: rgba(84,67,173,0.30);
}

/* List view card overrides */
.gp-grid--list .gp-card {
  flex-direction: row;
  align-items: center;
  gap: 24px;
  padding: 20px 24px;
}

.gp-grid--list .gp-card-meta  { flex-direction: row; gap: 16px; margin-bottom: 0; }
.gp-grid--list .gp-card-footer { margin-top: 0; margin-left: auto; flex-shrink: 0; }
.gp-grid--list .gp-card-desc  { display: none; }
.gp-grid--list .gp-card-title { margin-bottom: 6px; font-size: 14px; }
.gp-grid--list .gp-card-badge { margin-bottom: 6px; }

/* Card badge */
.gp-card-badge {
  display: inline-flex;
  align-items: center;
  background: rgba(84,67,173,0.08);
  color: #5443ad;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  padding: 4px 10px;
  border-radius: 100px;
  margin-bottom: 12px;
  width: fit-content;
}

/* Card title */
.gp-card-title {
  font-size: 15px;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.4;
  margin-bottom: 10px;
}

/* Card description */
.gp-card-desc {
  font-size: 13px;
  color: #6b7280;
  line-height: 1.6;
  margin-bottom: 16px;
  flex: 1;
}

/* Card meta */
.gp-card-meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 18px;
}

.gp-card-meta-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #6b7280;
}

.gp-meta-icon {
  width: 13px;
  height: 13px;
  color: #9ca3af;
  flex-shrink: 0;
}

/* Card footer CTA */
.gp-card-footer {
  margin-top: auto;
  padding-top: 16px;
  border-top: 1px solid #f1f1f4;
}

.gp-card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: #5443ad;
  transition: gap 0.18s ease;
}

.gp-card:hover .gp-card-link {
  gap: 9px;
}

/* ─── Empty state ─────────────────────────────────────── */
.gp-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 64px 0;
  color: #9ca3af;
  font-size: 14px;
}

/* ─── Responsive ──────────────────────────────────────── */
@media (max-width: 1024px) {
  .gp-programs-hero-inner,
  .gp-programs-body-inner { padding: 0 40px; }
  .gp-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .gp-programs-hero      { padding: 48px 0 44px; }
  .gp-programs-hero-inner,
  .gp-programs-body-inner { padding: 0 24px; }
  .gp-grid               { grid-template-columns: 1fr; }
  .gp-stats              { flex-wrap: wrap; gap: 16px; padding: 16px 20px; }
  .gp-stat               { padding: 0 16px; }
  .gp-stat-divider       { display: none; }
}

@media (max-width: 520px) {
  .gp-programs-hero-inner,
  .gp-programs-body-inner { padding: 0 16px; }
  .gp-programs-title      { font-size: 22px; }
  .gp-filter-tabs         { gap: 6px; }
  .gp-filter-tab          { font-size: 12px; padding: 6px 12px; }
}

sp_widget.script:
(function() {
  data.programs     = [];
  data.categoryList = [];
  data.activePrograms = 0;
  data.totalPrograms  = 0;
  data.categories     = 0;

  var gr = new GlideRecord('x_enno_gatenow_grant_program');
  gr.addQuery('active', true);
  gr.orderByDesc('sys_created_on');
  gr.query();

  var catSet = {};

  while (gr.next()) {
    var cat = gr.getDisplayValue('category') || ''; // ← confirm this exact field name in your table

    data.programs.push({
      sys_id:              gr.getUniqueValue(),
      program_name:        gr.getDisplayValue('program_name'),
      program_description: gr.getDisplayValue('program_description'),
      program_category:    cat,                              // ← must match what filter compares
      program_budget:      gr.getDisplayValue('program_budget'),
      proposal_open_date:  gr.getDisplayValue('proposal_open_date'),
      status:              gr.getDisplayValue('status')
    });

    if (cat) catSet[cat] = true;
  }

  data.totalPrograms  = data.programs.length;
  data.activePrograms = data.programs.length;
  data.categoryList   = Object.keys(catSet).sort();         // ← drives the filter tab buttons
  data.categories     = data.categoryList.length;
})();
